/** Test-only, independent reading of the exam's fixed spreadsheet expressions.
 * No production imports, eval, Function, JS compilation or arbitrary code execution.
 * Unknown tokens/functions, bad coordinates, unmatched ranges and wrong arity fail.
 */
export type Pm13Cell=string|number|boolean|null;
export type Pm13Sheets=Record<string,Map<string,Pm13Cell>>;
type Ref={kind:'ref';sheet:string;column:number;row:number;columnFixed:boolean;rowFixed:boolean};
type Range={kind:'range';from:Ref;to:Ref};
type Node=Ref|Range|{kind:'literal';value:Pm13Cell}|{kind:'name';name:string}|{kind:'binary';operator:string;left:Node;right:Node}|{kind:'call';name:string;args:Node[]};
type Matrix={kind:'matrix';rows:Pm13Cell[][]};
const columnNumber=(s:string)=>[...s].reduce((n,c)=>n*26+c.charCodeAt(0)-64,0),columnName=(n:number)=>{let s='';for(;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s;};
export function independentPm13Parse(text:string):Node{
 const tokens:string[]=[];let at=0;
 while(at<text.length){if(/\s/.test(text[at])){at++;continue;}const rest=text.slice(at),m=rest.match(/^(?:(?:ログ|曜日|集計|アクセス先集計)!)?\$?[A-Z]{1,2}\$?[0-9]+/)??rest.match(/^(?:[0-9]+(?:\.[0-9]+)?|[A-Za-z_][A-Za-z_0-9]*|[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}]+)/u)??rest.match(/^(?:≠|>=|<=|[(),:+\-*/／=<>])/);if(!m)throw Error('ORACLE_TOKEN:'+rest);tokens.push(m[0]);at+=m[0].length;}
 let i=0;const take=()=>tokens[i++],peek=()=>tokens[i],expect=(s:string)=>{if(take()!==s)throw Error('ORACLE_EXPECT:'+s);};
 function primary():Node{const token=take();if(!token)throw Error('ORACLE_EOF');if(token==='('){const node=compare();expect(')');return node;}if(token==='-')return{kind:'binary',operator:'-',left:{kind:'literal',value:0},right:primary()};if(/^\d/.test(token))return{kind:'literal',value:Number(token)};if(token==='null'||token==='true'||token==='false')return{kind:'literal',value:token==='null'?null:token==='true'};
  const ref=token.match(/^(?:(ログ|曜日|集計|アクセス先集計)!)?(\$?)([A-Z]+)(\$?)(\d+)$/);if(ref){const make=(m:RegExpMatchArray):Ref=>({kind:'ref',sheet:m[1]??'集計',column:columnNumber(m[3]),row:Number(m[5]),columnFixed:!!m[2],rowFixed:!!m[4]}),from=make(ref);if(peek()===':'){take();const other=take().match(/^(?:(ログ|曜日|集計|アクセス先集計)!)?(\$?)([A-Z]+)(\$?)(\d+)$/);if(!other)throw Error('ORACLE_RANGE');const to=make(other);if(!other[1])to.sheet=from.sheet;return{kind:'range',from,to};}return from;}
  if(peek()==='('){take();const args:Node[]=[];if(peek()!==')'){do{args.push(compare());if(peek()!==',')break;take();}while(true);}expect(')');return{kind:'call',name:token,args};}return{kind:'name',name:token};
 }
 function product():Node{let node=primary();while(['*','/','／'].includes(peek())){const operator=take();node={kind:'binary',operator,left:node,right:primary()};}return node;}
 function sum():Node{let node=product();while(['+','-'].includes(peek())){const operator=take();node={kind:'binary',operator,left:node,right:product()};}return node;}
 function compare():Node{let node=sum();if(['=','≠','>','<','>=','<='].includes(peek())){const operator=take();node={kind:'binary',operator,left:node,right:sum()};}return node;}
 const node=compare();if(i!==tokens.length)throw Error('ORACLE_TRAILING');return node;
}
export function independentPm13Copy(node:Node,dx:number,dy:number):Node{switch(node.kind){case'ref':return{...node,column:node.column+(node.columnFixed?0:dx),row:node.row+(node.rowFixed?0:dy)};case'range':return{kind:'range',from:independentPm13Copy(node.from,dx,dy) as Ref,to:independentPm13Copy(node.to,dx,dy) as Ref};case'binary':return{...node,left:independentPm13Copy(node.left,dx,dy),right:independentPm13Copy(node.right,dx,dy)};case'call':return{...node,args:node.args.map(n=>independentPm13Copy(n,dx,dy))};default:return{...node};}}
export function independentPm13Read(ref:Ref,sheets:Pm13Sheets):Pm13Cell{if(ref.row<1||ref.row>10000||ref.column<1||ref.column>256)throw Error('ORACLE_COORDINATE');return sheets[ref.sheet]?.get(columnName(ref.column)+ref.row)??null;}
function relative(node:Node,sheets:Pm13Sheets,env:Record<string,Pm13Cell>):Ref{if(node.kind!=='call'||node.name!=='相対'||node.args.length!==3||node.args[0].kind!=='ref')throw Error('ORACLE_RELATIVE');const from=node.args[0],dy=independentPm13Evaluate(node.args[1],sheets,env),dx=independentPm13Evaluate(node.args[2],sheets,env);if(typeof dx!=='number'||typeof dy!=='number'||!Number.isInteger(dx)||!Number.isInteger(dy))throw Error('ORACLE_RELATIVE_OFFSET');return{...from,row:from.row+dy,column:from.column+dx};}
export function independentPm13Evaluate(node:Node,sheets:Pm13Sheets,env:Record<string,Pm13Cell>={}):Pm13Cell|Matrix{
 const scalar=(n:Node)=>{const v=independentPm13Evaluate(n,sheets,env);if(typeof v==='object'&&v!==null)throw Error('ORACLE_SCALAR');return v;},numeric=(v:Pm13Cell)=>{if(typeof v!=='number'||!Number.isFinite(v))throw Error('ORACLE_NUMBER');return v;},matrix=(n:Node)=>{const v=independentPm13Evaluate(n,sheets,env);if(!v||typeof v!=='object'||v.kind!=='matrix')throw Error('ORACLE_MATRIX');return v.rows;};
 if(node.kind==='literal')return node.value;if(node.kind==='ref')return independentPm13Read(node,sheets);if(node.kind==='name'){if(!Object.hasOwn(env,node.name))throw Error('ORACLE_VARIABLE:'+node.name);return env[node.name];}
 if(node.kind==='range'){if(node.from.sheet!==node.to.sheet||node.to.row<node.from.row||node.to.column<node.from.column)throw Error('ORACLE_RANGE_ORDER');return{kind:'matrix',rows:Array.from({length:node.to.row-node.from.row+1},(_,r)=>Array.from({length:node.to.column-node.from.column+1},(_,c)=>independentPm13Read({...node.from,row:node.from.row+r,column:node.from.column+c},sheets)))};}
 if(node.kind==='binary'){const left=scalar(node.left),right=scalar(node.right);if(node.operator==='=')return left===right;if(node.operator==='≠')return left!==right;const a=numeric(left),b=numeric(right);switch(node.operator){case'+':return a+b;case'-':return a-b;case'*':return a*b;case'/':case'／':if(b===0)throw Error('ORACLE_DIVZERO');return a/b;case'>':return a>b;case'<':return a<b;case'>=':return a>=b;case'<=':return a<=b;default:throw Error('ORACLE_OPERATOR');}}
 const args=node.args,arity=(n:number)=>{if(args.length!==n)throw Error('ORACLE_ARITY');};switch(node.name){
 case'IF':arity(3);{const condition=scalar(args[0]);if(typeof condition!=='boolean')throw Error('ORACLE_BOOLEAN');return independentPm13Evaluate(args[condition?1:2],sheets,env);}
 case'剰余':arity(2);{const a=numeric(scalar(args[0])),b=numeric(scalar(args[1]));if(b===0)throw Error('ORACLE_DIVZERO');return a-b*Math.floor(a/b);}
 case'切上げ':case'切捨て':case'四捨五入':arity(2);{const x=numeric(scalar(args[0])),digits=numeric(scalar(args[1]));if(digits!==0||x<0)throw Error('ORACLE_ROUND_DOMAIN');return node.name==='切上げ'?Math.ceil(x):node.name==='切捨て'?Math.trunc(x):Math.floor(x+.5);}
 case'結合':if(!args.length)throw Error('ORACLE_ARITY');return args.map(n=>String(scalar(n))).join('');
 case'最大':arity(1);{const numbers=matrix(args[0]).flat().filter((x):x is number=>typeof x==='number');if(!numbers.length)throw Error('ORACLE_EMPTY_MAX');return Math.max(...numbers);}
 case'照合一致':arity(3);{const target=scalar(args[0]),values=matrix(args[1]);if(numeric(scalar(args[2]))!==0||values.length!==1&&values[0].length!==1)throw Error('ORACLE_LOOKUP_SHAPE');const index=values.flat().findIndex(x=>x===target);if(index<0)throw Error('ORACLE_NOT_FOUND');return index+1;}
 case'照合検索':arity(3);{const target=scalar(args[0]),search=matrix(args[1]),extract=matrix(args[2]);if(search.length!==1&&search[0].length!==1||extract.length!==1&&extract[0].length!==1||search.flat().length!==extract.flat().length)throw Error('ORACLE_LOOKUP_SHAPE');const index=search.flat().findIndex(x=>x===target);if(index<0)throw Error('ORACLE_NOT_FOUND');return extract.flat()[index];}
 case'水平照合':arity(4);{const target=scalar(args[0]),table=matrix(args[1]),row=numeric(scalar(args[2]));if(numeric(scalar(args[3]))!==0||row<1||row>table.length)throw Error('ORACLE_LOOKUP_SHAPE');const index=table[0].findIndex(x=>x===target);if(index<0)throw Error('ORACLE_NOT_FOUND');return table[row-1][index];}
 case'表引き':arity(3);{const table=matrix(args[0]),row=numeric(scalar(args[1])),column=numeric(scalar(args[2]));if(!Number.isInteger(row)||!Number.isInteger(column)||row<1||row>table.length||column<1||column>table[0].length)throw Error('ORACLE_LOOKUP_SHAPE');return table[row-1][column-1];}
 case'論理積':case'論理和':{const values=args.map(scalar);if(!values.length||values.some(x=>typeof x!=='boolean'))throw Error('ORACLE_BOOLEAN');return node.name==='論理積'?values.every(Boolean):values.some(Boolean);}
 case'相対':return independentPm13Read(relative(node,sheets,env),sheets);
 default:throw Error('ORACLE_FUNCTION:'+node.name);
 }
}
export function independentPm13Assign(statement:string,sheets:Pm13Sheets,env:Record<string,Pm13Cell>){const parts=statement.split('←');if(parts.length!==2)throw Error('ORACLE_ASSIGN');const ref=relative(independentPm13Parse(parts[0]),sheets,env),value=independentPm13Evaluate(independentPm13Parse(parts[1]),sheets,env);if(value&&typeof value==='object')throw Error('ORACLE_ASSIGN_SCALAR');independentPm13Read(ref,sheets);const sheet=sheets[ref.sheet]??(sheets[ref.sheet]=new Map());sheet.set(columnName(ref.column)+ref.row,value);}
export function independentPm13Calendar(minute:number){if(!Number.isInteger(minute)||minute<0)throw Error('ORACLE_TIME_DOMAIN');const date=new Date(minute*60000),hour=date.getUTCHours(),dayCode=(date.getUTCDay()+3)%7;return{hour,dayCode,key:String(hour)+String(dayCode)};}
export function independentPm13URLCounts(urls:string[]){const unique:string[]=[],counts:number[]=[];for(const url of urls){let at=unique.indexOf(url);if(at<0){at=unique.length;unique.push(url);counts.push(0);}counts[at]++;}return unique.map((url,i)=>[url,counts[i]] as const);}
export function independentPm13RunMacro(input:string[],d:string,e:string,f:string){const parsedD=independentPm13Parse(d),parsedE=independentPm13Parse(e),sheets:Pm13Sheets={ログ:new Map(),集計:new Map()},env:Record<string,Pm13Cell>={log_line:1,count_line:1,log_url:null,count_url:null};input.forEach((value,i)=>sheets.ログ.set('C'+(i+2),value));let steps=0;const tick=()=>{if(++steps>Math.min(200000000,(input.length+1)**2*5+100))throw Error('ORACLE_MACRO_NONTERMINATION');};
 while(sheets.ログ.has('C'+(Number(env.log_line)+1))){tick();env.count_line=1;env.log_url=sheets.ログ.get('C'+(Number(env.log_line)+1))!;env.count_url=sheets.集計.get('A2')??null;while(independentPm13Evaluate(parsedD,sheets,env)===true){tick();env.count_line=Number(env.count_line)+1;if(Number(env.count_line)>9999)throw Error('ORACLE_MACRO_BOUNDARY');env.count_url=sheets.集計.get('A'+(Number(env.count_line)+1))??null;}if(independentPm13Evaluate(parsedE,sheets,env)===true){sheets.集計.set('A'+(Number(env.count_line)+1),env.log_url);sheets.集計.set('B'+(Number(env.count_line)+1),1);}else independentPm13Assign(f,sheets,env);env.log_line=Number(env.log_line)+1;}
 const output:[Pm13Cell,Pm13Cell][]=[];for(let row=2;row<=Math.min(10000,input.length+2);row++){const url=sheets.集計.get('A'+row)??null,count=sheets.集計.get('B'+row)??null;if(url!==null||count!==null)output.push([url,count]);}return{output,steps,sheets};}
